boolean isPrime(int n) {
    if (n < 2) return false;             // 0, 1, negatives: not prime
    for (int i = 2; (long) i * i <= n; i++) {   // only up to sqrt(n)
        if (n % i == 0) return false;    // found a divisor
    }
    return true;
}

// n = 37: check i=2..6 (since 6*6=36<=37, 7*7=49>37)
// none divide 37 -> prime
// n = 91: i=7 divides (7*13) -> not prime
```
Using `i * i <= n` avoids computing `Math.sqrt` and the floating-point edge cases.

