int secondLargest(int[] a) {
    int largest = Integer.MIN_VALUE, second = Integer.MIN_VALUE;
    for (int x : a) {
        if (x > largest) { second = largest; largest = x; }   // shift down
        else if (x > second && x != largest) second = x;      // distinct second
    }
    return second;
}

// {10, 5, 10, 8}: largest->10, then 5(second=5), 10(skip,==largest), 8(second=8)
// returns 8
```

